import{_ as a,o as t,c as l,ac as i}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"中国共产党第十一届中央委员会第五次全体会议","description":"","frontmatter":{"prev":{"text":"中国共产党第十一届中央委员会第四次全体会议公报","link":"../4/中国共产党第十一届中央委员会第四次全体会议公报"},"next":{"text":"中国共产党第十一届中央委员会第五次全体会议关于召开党的第十二次全国代表大会的决议","link":"./中国共产党第十一届中央委员会第五次全体会议关于召开党的第十二次全国代表大会的决议"}},"headers":[],"relativePath":"11/5/index.md","filePath":"11/5/index.md"}'),r={name:"11/5/index.md"};function n(o,e,_,s,d,h){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="中国共产党第十一届中央委员会第五次全体会议" tabindex="-1">中国共产党第十一届中央委员会第五次全体会议 <a class="header-anchor" href="#中国共产党第十一届中央委员会第五次全体会议" aria-label="Permalink to &quot;中国共产党第十一届中央委员会第五次全体会议&quot;">​</a></h1><p>1980年2月23～29日在北京举行。全会的大部分议程是关于加强和改善党的领导，以适应发展社会主义现代化建设的需要。通过7项决定：提前召开中共十二次代表大会；《中国共产党章程（草案）》；《关于党内政治生活的若干准则》；增选胡耀邦、赵紫阳为政治局常委，重新设立中共中央书记处，选举胡耀邦为中央委员会总书记，万里、王任重、方毅、谷牧、宋任穷、余秋里、杨得志、胡乔木、胡耀邦、姚依林、彭冲为中共中央书记处书记；彻底为刘少奇同志平反，撤销八届十二中全会强加给他的“叛徒、内奸、工贼”的罪名和把他“永远开除出党，撤销其党内外的一切职务”的错误决议，撤销原审查报告，恢复刘少奇同志作为伟大的马克思主义者和无产阶级革命家、党和国家的主要领导人之一的名誉，因刘少奇同志问题受株连造成的冤假错案，由有关部门予以平反；批准汪东兴、纪登奎、吴德、陈锡联的辞职请求，免除或提请免除他们所担任的党和国家的领导职务；建议全国人民代表大会修改宪法第45条，取消公民“有运用大鸣、大放、大辩论、大字报的权利”的规定。</p><ul><li><a href="./中国共产党第十一届中央委员会第五次全体会议关于召开党的第十二次全国代表大会的决议.html">中国共产党第十一届中央委员会第五次全体会议关于召开党的第十二次全国代表大会的决议</a></li><li><a href="./中国共产党第十一届中央委员会第五次全体会议关于成立中央书记处的决议.html">中国共产党第十一届中央委员会第五次全体会议关于成立中央书记处的决议</a></li><li><a href="./关于党内政治生活的若干准则.html">关于党内政治生活的若干准则</a></li><li><a href="./中国共产党第十一届中央委员会第五次全体会议关于为刘少奇同志平反的决议.html">中国共产党第十一届中央委员会第五次全体会议关于为刘少奇同志平反的决议</a></li><li><a href="./中国共产党第十一届中央委员会第五次全体会议公报.html">中国共产党第十一届中央委员会第五次全体会议公报</a></li></ul>',3)])])}const f=a(r,[["render",n]]);export{m as __pageData,f as default};
